export const CHAPTERS = [{"t": 0, "title": "Clay and fire"}, {"t": 46.2, "title": "Rice and mirrors"}, {"t": 77.4, "title": "Keyholes"}, {"t": 104.1, "title": "The rising sun"}, {"t": 168.9, "title": "The Great Buddha"}, {"t": 190.1, "title": "The court of beauty"}, {"t": 232.4, "title": "The warriors"}, {"t": 276.0, "title": "Gold and stillness"}, {"t": 337.7, "title": "Guns and tea"}, {"t": 389.7, "title": "The floating world"}, {"t": 460.5, "title": "Black ships"}, {"t": 511.2, "title": "Empire and ashes"}, {"t": 574.4, "title": "The miracle"}, {"t": 661.1, "title": "Ink and light"}, {"t": 722.3, "title": "The hands"}, {"t": 798.6, "title": "Mended with gold"}];
export const CUES = [{"t": 4.5, "end": 13.19, "lines": [{"t0": 4.5, "t1": 7.18, "text": "More than fifteen thousand years ago,"}, {"t0": 7.18, "t1": 13.79, "text": "on a chain of green islands at the edge of Asia, people began to fire pots of clay."}]}, {"t": 15.0, "end": 17.47, "lines": [{"t0": 15.0, "t1": 18.07, "text": "They are among the oldest pots in the world."}]}, {"t": 20.5, "end": 27.75, "lines": [{"t0": 20.5, "t1": 24.37, "text": "Later potters rolled twisted cord across the wet clay,"}, {"t0": 24.37, "t1": 28.35, "text": "so we call these people the J\u014dmon: cord-marked."}]}, {"t": 29.7, "end": 36.64, "lines": [{"t0": 29.7, "t1": 32.87, "text": "They fished, hunted and gathered chestnuts,"}, {"t0": 32.87, "t1": 37.24, "text": "and some of their villages lasted a thousand years."}]}, {"t": 38.6, "end": 44.78, "lines": [{"t0": 38.6, "t1": 41.91, "text": "Their potters made pots with rims like flames,"}, {"t0": 41.91, "t1": 45.38, "text": "and clay figures with great goggle eyes."}]}, {"t": 47.9, "end": 53.49, "lines": [{"t0": 47.9, "t1": 51.63, "text": "Then rice farming came across the sea from the mainland,"}, {"t0": 51.63, "t1": 54.09, "text": "and with it bronze and iron."}]}, {"t": 55.1, "end": 61.13, "lines": [{"t0": 55.1, "t1": 57.93, "text": "Villages dug moats, built watchtowers,"}, {"t0": 57.93, "t1": 61.73, "text": "and kept their rice in granaries on stilts."}]}, {"t": 62.9, "end": 69.8, "lines": [{"t0": 62.9, "t1": 66.51, "text": "A Chinese chronicle tells of a queen, Himiko,"}, {"t0": 66.51, "t1": 70.4, "text": "who ruled by sorcery and was seldom seen."}]}, {"t": 71.0, "end": 76.05, "lines": [{"t0": 71.0, "t1": 73.99, "text": "The emperor of Wei sent her a golden seal,"}, {"t0": 73.99, "t1": 76.65, "text": "and a hundred bronze mirrors."}]}, {"t": 79.1, "end": 85.87, "lines": [{"t0": 79.1, "t1": 82.75, "text": "Japan's early kings were buried in great mounds,"}, {"t0": 82.75, "t1": 86.47, "text": "shaped like keyholes and ringed by moats."}]}, {"t": 87.5, "end": 94.0, "lines": [{"t0": 87.5, "t1": 91.2, "text": "On them stood hollow clay figures, called haniwa:"}, {"t0": 91.2, "t1": 94.6, "text": "houses, horses, warriors and dancers."}]}, {"t": 95.8, "end": 102.71, "lines": [{"t0": 95.8, "t1": 99.55, "text": "From these kings descends Japan's imperial family,"}, {"t0": 99.55, "t1": 103.31, "text": "the oldest reigning monarchy in the world."}]}, {"t": 105.8, "end": 112.94, "lines": [{"t0": 105.8, "t1": 109.16, "text": "In the sixth century, Buddhism came from Korea,"}, {"t0": 109.16, "t1": 113.54, "text": "with its scriptures, its statues, and its carpenters."}]}, {"t": 114.5, "end": 120.45, "lines": [{"t0": 114.5, "t1": 116.53, "text": "Prince Sh\u014dtoku, it is said,"}, {"t0": 116.53, "t1": 121.05, "text": "wrote that harmony is to be valued above all things."}]}, {"t": 122.0, "end": 127.69, "lines": [{"t0": 122.0, "t1": 124.71, "text": "A letter to the emperor of China began:"}, {"t0": 124.71, "t1": 128.29, "text": "from the Son of Heaven where the sun rises."}]}, {"t": 128.7, "end": 134.74, "lines": [{"t0": 128.7, "t1": 132.55, "text": "Before long the country took the name it still has:"}, {"t0": 132.55, "t1": 135.34, "text": "Nihon, the origin of the sun."}]}, {"t": 137.5, "end": 144.3, "lines": [{"t0": 137.5, "t1": 139.79, "text": "The temple he founded, H\u014dry\u016b-ji,"}, {"t0": 139.79, "t1": 144.9, "text": "has the oldest wooden buildings standing anywhere in the world."}]}, {"t": 145.9, "end": 153.71, "lines": [{"t0": 145.9, "t1": 149.64, "text": "One firm of temple carpenters, founded in 578,"}, {"t0": 149.64, "t1": 154.31, "text": "kept working for more than fourteen hundred years."}]}, {"t": 155.9, "end": 167.51, "lines": [{"t0": 155.9, "t1": 161.74, "text": "And at Ise, the holiest shrine is rebuilt from fresh cypress every twenty years,"}, {"t0": 161.74, "t1": 168.11, "text": "as it has been since the seventh century, so that the craft is never forgotten."}]}, {"t": 170.6, "end": 179.03, "lines": [{"t0": 170.6, "t1": 174.09, "text": "At Nara, an emperor cast a Buddha of bronze,"}, {"t0": 174.09, "t1": 176.28, "text": "fifteen metres tall."}, {"t0": 176.14, "t1": 179.63, "text": "It used up most of the country's bronze."}]}, {"t": 181.0, "end": 188.67, "lines": [{"t0": 181.0, "t1": 185.47, "text": "Its eyes were painted in with a great brush, tied to long cords,"}, {"t0": 185.47, "t1": 189.27, "text": "so that thousands of people could hold it too."}]}, {"t": 191.8, "end": 199.4, "lines": [{"t0": 191.8, "t1": 196.32, "text": "The capital moved to Heian-ky\u014d, today's Kyoto."}, {"t0": 196.18, "t1": 200.0, "text": "It would stay there for more than a thousand years."}]}, {"t": 201.0, "end": 208.88, "lines": [{"t0": 201.0, "t1": 205.36, "text": "Its court lived for beauty: for poetry, incense, moon-viewing,"}, {"t0": 205.36, "t1": 209.48, "text": "and robes of twelve layers, matched to the season."}]}, {"t": 210.9, "end": 215.05, "lines": [{"t0": 210.9, "t1": 215.65, "text": "Women at court wrote in a new, flowing script, called kana."}]}, {"t": 216.6, "end": 223.45, "lines": [{"t0": 216.6, "t1": 220.36, "text": "And Murasaki Shikibu wrote The Tale of Genji,"}, {"t0": 220.36, "t1": 224.05, "text": "often called the world's first novel."}]}, {"t": 225.0, "end": 231.04, "lines": [{"t0": 225.0, "t1": 227.4, "text": "In the painted scrolls of the tale,"}, {"t0": 227.4, "t1": 231.64, "text": "the roofs are lifted away, so that we can see inside."}]}, {"t": 234.1, "end": 244.53, "lines": [{"t0": 234.1, "t1": 236.97, "text": "Then the samurai took power."}, {"t0": 236.83, "t1": 240.99, "text": "The emperor still reigned, but a military ruler, the shogun,"}, {"t0": 240.99, "t1": 245.13, "text": "governed, for most of the next seven hundred years."}]}, {"t": 246.3, "end": 256.76, "lines": [{"t0": 246.3, "t1": 249.22, "text": "Twice, the Mongols sailed against Japan,"}, {"t0": 249.22, "t1": 252.82, "text": "and twice, storms helped drive them back."}, {"t0": 252.68, "t1": 257.36, "text": "People called them kamikaze: winds of the gods."}]}, {"t": 259.6, "end": 264.69, "lines": [{"t0": 259.6, "t1": 262.92, "text": "Swordsmiths folded their steel again and again,"}, {"t0": 262.92, "t1": 265.29, "text": "into thousands of layers."}]}, {"t": 265.5, "end": 274.6, "lines": [{"t0": 265.5, "t1": 267.69, "text": "They coated the blade in clay,"}, {"t0": 267.69, "t1": 271.0, "text": "heated it, and plunged it into water."}, {"t0": 270.86, "t1": 275.2, "text": "The edge turned hard, and the blade took on its curve."}]}, {"t": 277.7, "end": 284.39, "lines": [{"t0": 277.7, "t1": 279.9, "text": "Under the Ashikaga shoguns,"}, {"t0": 279.9, "t1": 284.99, "text": "a pavilion covered in gold leaf rose over a quiet pond."}]}, {"t": 286.0, "end": 292.84, "lines": [{"t0": 286.0, "t1": 288.61, "text": "Actors in carved masks performed Noh,"}, {"t0": 288.61, "t1": 293.44, "text": "a theatre still played much as it was six hundred years ago."}]}, {"t": 294.6, "end": 299.34, "lines": [{"t0": 294.6, "t1": 299.94, "text": "Zen monks raked gardens of gravel and stone, to quiet the mind."}]}, {"t": 301.5, "end": 311.03, "lines": [{"t0": 301.5, "t1": 307.4, "text": "There is a story that a shogun sent a cracked tea bowl to China for repair."}, {"t0": 307.26, "t1": 311.63, "text": "It came back held together with ugly metal staples."}]}, {"t": 311.8, "end": 321.3, "lines": [{"t0": 311.8, "t1": 315.54, "text": "So Japanese craftsmen found another way."}, {"t0": 315.4, "t1": 317.77, "text": "They mended it with lacquer and gold,"}, {"t0": 317.77, "t1": 321.9, "text": "and made the break the most beautiful part of the bowl."}]}, {"t": 322.7, "end": 325.98, "lines": [{"t0": 322.7, "t1": 326.58, "text": "It is called kintsugi: golden joinery."}]}, {"t": 328.6, "end": 336.26, "lines": [{"t0": 328.6, "t1": 331.24, "text": "Then the great lords fell out."}, {"t0": 331.1, "t1": 333.56, "text": "Kyoto burned, and for a century,"}, {"t0": 333.56, "t1": 336.86, "text": "the country was at war with itself."}]}, {"t": 339.4, "end": 348.44, "lines": [{"t0": 339.4, "t1": 344.74, "text": "In 1543, Portuguese traders brought guns to Japan."}, {"t0": 344.6, "t1": 349.04, "text": "Within a few years, Japanese smiths were making their own."}]}, {"t": 350.0, "end": 357.26, "lines": [{"t0": 350.0, "t1": 354.53, "text": "Three warlords, one after another, forced the country back together,"}, {"t0": 354.53, "t1": 357.86, "text": "and built great white castles to hold it."}]}, {"t": 359.5, "end": 371.28, "lines": [{"t0": 359.5, "t1": 365.51, "text": "Amid the wars, the tea master Sen no Riky\u016b built a tea room just two mats wide,"}, {"t0": 365.51, "t1": 371.88, "text": "with a door so low that every guest had to bow, and leave his sword outside."}]}, {"t": 372.7, "end": 376.3, "lines": [{"t0": 372.7, "t1": 376.9, "text": "His lord, Hideyoshi, had one made of gold."}]}, {"t": 378.5, "end": 388.32, "lines": [{"t0": 378.5, "t1": 382.36, "text": "In 1600, in the morning fog at Sekigahara,"}, {"t0": 382.36, "t1": 388.92, "text": "Tokugawa Ieyasu won the battle that decided who would rule Japan."}]}, {"t": 391.4, "end": 394.55, "lines": [{"t0": 391.4, "t1": 395.15, "text": "Then came two and a half centuries of peace."}]}, {"t": 395.7, "end": 403.74, "lines": [{"t0": 395.7, "t1": 398.44, "text": "Japan closed its doors."}, {"t0": 398.3, "t1": 401.58, "text": "Only Dutch and Chinese ships could trade,"}, {"t0": 401.58, "t1": 404.34, "text": "at a single port: Nagasaki."}]}, {"t": 405.7, "end": 411.92, "lines": [{"t0": 405.7, "t1": 409.24, "text": "Edo, today's Tokyo, grew to a million people,"}, {"t0": 409.24, "t1": 412.52, "text": "perhaps the largest city on Earth."}]}, {"t": 413.5, "end": 421.77, "lines": [{"t0": 413.5, "t1": 418.17, "text": "Its people ate sushi from street stalls, crowded into kabuki theatres,"}, {"t0": 418.17, "t1": 422.37, "text": "and watched fireworks over the river on summer nights."}]}, {"t": 424.8, "end": 432.12, "lines": [{"t0": 424.8, "t1": 428.27, "text": "The poet Bash\u014d wrote: An old pond."}, {"t0": 428.13, "t1": 430.44, "text": "A frog jumps in."}, {"t0": 430.3, "t1": 432.72, "text": "The sound of water."}]}, {"t": 435.3, "end": 443.94, "lines": [{"t0": 435.3, "t1": 440.17, "text": "Artists made woodblock prints, carved and printed one colour at a time,"}, {"t0": 440.17, "t1": 444.54, "text": "and sold them for about the price of a bowl of noodles."}]}, {"t": 445.5, "end": 448.95, "lines": [{"t0": 445.5, "t1": 449.55, "text": "The most famous is Hokusai's Great Wave."}]}, {"t": 453.5, "end": 459.13, "lines": [{"t0": 453.5, "t1": 455.42, "text": "When Europe saw these prints,"}, {"t0": 455.42, "t1": 459.73, "text": "painters like Van Gogh and Monet fell in love with them."}]}, {"t": 462.2, "end": 472.56, "lines": [{"t0": 462.2, "t1": 467.86, "text": "In 1853, American warships, black-hulled and trailing coal smoke,"}, {"t0": 467.86, "t1": 473.16, "text": "steamed into Edo Bay, and demanded that Japan open up."}]}, {"t": 474.2, "end": 482.0, "lines": [{"t0": 474.2, "t1": 479.28, "text": "Fifteen years later the shogun fell, and under the young emperor Meiji,"}, {"t0": 479.28, "t1": 482.6, "text": "Japan raced to catch up with the West."}]}, {"t": 483.6, "end": 491.47, "lines": [{"t0": 483.6, "t1": 486.57, "text": "Samurai cut off their topknots."}, {"t0": 486.43, "t1": 488.88, "text": "Within a generation came railways,"}, {"t0": 488.88, "t1": 492.07, "text": "factories, schools and a parliament."}]}, {"t": 493.1, "end": 500.43, "lines": [{"t0": 493.1, "t1": 497.09, "text": "The far north, land of the Ainu, became Hokkaido,"}, {"t0": 497.09, "t1": 501.03, "text": "and the kingdom of Ryukyu became Okinawa."}]}, {"t": 502.0, "end": 509.85, "lines": [{"t0": 502.0, "t1": 504.47, "text": "In 1905, it defeated Russia:"}, {"t0": 504.47, "t1": 510.45, "text": "the first Asian power in modern times to beat a European one."}]}, {"t": 512.9, "end": 524.5, "lines": [{"t0": 512.9, "t1": 518.9, "text": "Japan made Korea a colony, and in the 1930s invaded China."}, {"t0": 518.76, "t1": 520.39, "text": "Its armies brought war,"}, {"t0": 520.39, "t1": 525.1, "text": "massacre and forced labour across Asia, and millions died."}]}, {"t": 526.7, "end": 531.47, "lines": [{"t0": 526.7, "t1": 532.07, "text": "In 1941, it attacked the United States at Pearl Harbor."}]}, {"t": 533.7, "end": 541.92, "lines": [{"t0": 533.7, "t1": 537.39, "text": "American bombers burned Japan's cities."}, {"t0": 537.25, "t1": 538.81, "text": "In one night in Tokyo,"}, {"t0": 538.81, "t1": 542.52, "text": "about a hundred thousand people were killed."}]}, {"t": 544.9, "end": 551.36, "lines": [{"t0": 544.9, "t1": 546.39, "text": "In August 1945,"}, {"t0": 546.39, "t1": 551.96, "text": "two atomic bombs destroyed Hiroshima and Nagasaki."}]}, {"t": 555.9, "end": 560.17, "lines": [{"t0": 555.9, "t1": 558.24, "text": "Japan surrendered."}, {"t0": 558.1, "t1": 560.77, "text": "Its cities lay in ashes."}]}, {"t": 563.2, "end": 573.05, "lines": [{"t0": 563.2, "t1": 567.39, "text": "In Hiroshima, a girl named Sadako, sick from the bomb,"}, {"t0": 567.39, "t1": 571.17, "text": "folded more than a thousand paper cranes."}, {"t0": 571.03, "t1": 573.65, "text": "They have become a wish for peace."}]}, {"t": 576.1, "end": 581.32, "lines": [{"t0": 576.1, "t1": 577.79, "text": "Japan rebuilt itself,"}, {"t0": 577.79, "t1": 581.92, "text": "under a new constitution that renounced war."}]}, {"t": 582.9, "end": 587.95, "lines": [{"t0": 582.9, "t1": 584.63, "text": "For almost twenty years,"}, {"t0": 584.63, "t1": 588.55, "text": "its economy grew by around ten percent a year."}]}, {"t": 589.5, "end": 602.11, "lines": [{"t0": 589.5, "t1": 594.9, "text": "At Toyota, any worker could stop the whole assembly line by pulling a cord,"}, {"t0": 594.9, "t1": 597.8, "text": "to fix a problem where it began."}, {"t0": 597.66, "t1": 602.71, "text": "Improving everything, a little, every day, was called kaizen."}]}, {"t": 604.1, "end": 612.41, "lines": [{"t0": 604.1, "t1": 607.96, "text": "Sony made a radio small enough for a shirt pocket."}, {"t0": 607.82, "t1": 613.01, "text": "Almost: its salesmen wore shirts with slightly larger pockets."}]}, {"t": 614.6, "end": 624.64, "lines": [{"t0": 614.6, "t1": 618.9, "text": "In 1964, Tokyo held the Olympics."}, {"t0": 618.76, "t1": 620.06, "text": "Nine days before,"}, {"t0": 620.06, "t1": 625.24, "text": "the world's first high-speed railway opened: the Shinkansen."}]}, {"t": 626.2, "end": 632.63, "lines": [{"t0": 626.2, "t1": 630.22, "text": "Its bullet trains have since carried billions of passengers,"}, {"t0": 630.22, "t1": 633.23, "text": "without one being killed in a crash."}]}, {"t": 634.6, "end": 640.12, "lines": [{"t0": 634.6, "t1": 640.72, "text": "By 1968, Japan had the second largest economy in the world."}]}, {"t": 642.1, "end": 654.6, "lines": [{"t0": 642.1, "t1": 645.66, "text": "In the 1980s its cities glowed."}, {"t0": 645.52, "t1": 655.2, "text": "Land in Tokyo became so precious that the grounds of the Imperial Palace were said to be worth more than all of California."}]}, {"t": 656.6, "end": 659.68, "lines": [{"t0": 656.6, "t1": 660.28, "text": "Then, in 1990, the bubble burst."}]}, {"t": 662.8, "end": 673.74, "lines": [{"t0": 662.8, "t1": 669.76, "text": "Meanwhile, a young medical student named Osamu Tezuka was drawing comics like films:"}, {"t0": 669.76, "t1": 674.34, "text": "close-ups, long shots, and big, expressive eyes."}]}, {"t": 675.3, "end": 685.3, "lines": [{"t0": 675.3, "t1": 678.78, "text": "Manga became something everyone read."}, {"t0": 678.64, "t1": 679.33, "text": "In 1995,"}, {"t0": 679.33, "t1": 685.9, "text": "one weekly manga magazine sold more than six million copies an issue."}]}, {"t": 686.9, "end": 692.27, "lines": [{"t0": 686.9, "t1": 689.75, "text": "Its stories came to life as anime,"}, {"t0": 689.75, "t1": 692.87, "text": "drawn by hand, frame by frame."}]}, {"t": 693.5, "end": 700.2, "lines": [{"t0": 693.5, "t1": 695.91, "text": "For one four-second crowd scene,"}, {"t0": 695.91, "t1": 700.8, "text": "an animator at Studio Ghibli worked for more than a year."}]}, {"t": 702.6, "end": 710.1, "lines": [{"t0": 702.6, "t1": 706.19, "text": "Hayao Miyazaki's Spirited Away won an Oscar,"}, {"t0": 706.19, "t1": 710.7, "text": "and manga, anime and games went round the world."}]}, {"t": 711.7, "end": 720.87, "lines": [{"t0": 711.7, "t1": 716.54, "text": "Nintendo, founded in 1889 to make playing cards by hand,"}, {"t0": 716.54, "t1": 721.47, "text": "became a maker of games played all over the world."}]}, {"t": 724.0, "end": 736.69, "lines": [{"t0": 724.0, "t1": 726.47, "text": "The old crafts carry on."}, {"t0": 726.33, "t1": 732.14, "text": "Japan has more companies over a hundred years old than any other country."}, {"t0": 732.0, "t1": 737.29, "text": "One inn has been run by the same family since 705."}]}, {"t": 738.3, "end": 749.65, "lines": [{"t0": 738.3, "t1": 741.14, "text": "Sushi chefs train for years."}, {"t0": 741.0, "t1": 744.0, "text": "Swordsmiths still fold their steel."}, {"t0": 743.86, "t1": 744.88, "text": "And in 2013,"}, {"t0": 744.88, "t1": 750.25, "text": "the shrine at Ise was rebuilt for the sixty-second time."}]}, {"t": 752.7, "end": 763.11, "lines": [{"t0": 752.7, "t1": 755.74, "text": "In 2011, the sea rose."}, {"t0": 755.6, "t1": 760.0, "text": "A tsunami left nearly twenty thousand people dead or missing,"}, {"t0": 760.0, "t1": 763.71, "text": "and wrecked the nuclear plant at Fukushima."}]}, {"t": 765.5, "end": 773.85, "lines": [{"t0": 765.5, "t1": 770.62, "text": "Along that coast stand old stones, carved by earlier generations:"}, {"t0": 770.62, "t1": 774.45, "text": "Do not build your homes below this point."}]}, {"t": 776.1, "end": 780.39, "lines": [{"t0": 776.1, "t1": 777.64, "text": "Where the water stopped,"}, {"t0": 777.64, "t1": 780.99, "text": "people are planting a line of cherry trees."}]}, {"t": 783.4, "end": 792.18, "lines": [{"t0": 783.4, "t1": 788.9, "text": "Its engineers have built a train that floats at six hundred kilometres an hour,"}, {"t0": 788.9, "t1": 792.78, "text": "and probes that bring back dust from asteroids."}]}, {"t": 793.8, "end": 797.17, "lines": [{"t0": 793.8, "t1": 797.77, "text": "Its people live some of the longest lives on Earth."}]}, {"t": 800.3, "end": 806.81, "lines": [{"t0": 800.3, "t1": 803.26, "text": "This country has been broken many times:"}, {"t0": 803.26, "t1": 807.41, "text": "by war and fire, by earthquakes, and by the sea."}]}, {"t": 808.8, "end": 812.17, "lines": [{"t0": 808.8, "t1": 812.77, "text": "Each time, it was mended, carefully, by hand."}]}, {"t": 814.8, "end": 821.03, "lines": [{"t0": 814.8, "t1": 819.72, "text": "And like a bowl mended with gold, it does not hide its seams."}, {"t0": 819.58, "t1": 821.63, "text": "It lets them shine."}]}];
